  mass=np.bincount(faces.ravel(),weights=bc.ravel(),minlength=len(growth.data.vertices));k=int(mass.argmax());V=raw(growth);edit=V.copy();edit[k,2]+=.0002;put(growth,edit);delta=np.linalg.norm(q.hair(hair)-before,axis=1);err=root_error();assert err<3e-6 and delta.max()>1e-6;ops['actualGrowthSurfaceVertexEdit']={'growthVertex':k,'requestedM':.0002,'visibleHairMaxM':float(delta.max()),'actualCurveRootsAgainstOwnEvaluatedTriangleFramesMaxM':err,'pointsAbove1um':int((delta>1e-6).sum())};put(growth,V);assert np.array_equal(q.hair(hair),before)
