  mask=np.ones(len(before)-1,bool);mask[(np.cumsum(counts)-1)[:-1]]=False;srcLen=np.linalg.norm(np.diff(line['sourceInitialWorld'],axis=0),axis=1)[mask];outLen=np.linalg.norm(np.diff(line['retargetedWorld'],axis=0),axis=1)[mask];chordError=float(abs(srcLen-outLen).max());assert chordError<1e-8
